def rainbow(k,order):
 alpha=math.acos(math.sqrt((k*k-1)/((order+1)**2-1)));beta=math.asin(math.sin(alpha)/k);D=order*math.pi+2*alpha-2*(order+1)*beta
 return alpha*180/math.pi,D*180/math.pi
